package consensus

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// Replays the replication conformance vectors (vectors/replication/*.trace,
// generated by orderer-rust's simulator) against this implementation.

func hexs(d []byte) string {
	if len(d) == 0 {
		return "-"
	}
	return fmt.Sprintf("%x", d)
}

func unhex(s string) []byte {
	if s == "-" {
		return nil
	}
	b := make([]byte, len(s)/2)
	for i := range b {
		v, _ := strconv.ParseUint(s[2*i:2*i+2], 16, 8)
		b[i] = byte(v)
	}
	return b
}

func fmtEntry(e Entry) string { return fmt.Sprintf("%d:%s", e.Term, hexs(e.Data)) }

func fmtEntries(es []Entry) string {
	if len(es) == 0 {
		return "-"
	}
	p := make([]string, len(es))
	for i, e := range es {
		p[i] = fmtEntry(e)
	}
	return strings.Join(p, ",")
}

func parseEntries(s string) []Entry {
	if s == "-" {
		return nil
	}
	var v []Entry
	for _, part := range strings.Split(s, ",") {
		c := strings.IndexByte(part, ':')
		t, _ := strconv.ParseUint(part[:c], 10, 32)
		v = append(v, Entry{Term: Term(t), Data: unhex(part[c+1:])})
	}
	return v
}

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

func fmtMsg(m Msg) string {
	switch m.Kind {
	case MsgVote:
		return fmt.Sprintf("vote %d %d %d %d", m.Term, m.LastIndex, m.LastTerm, b2i(m.Pre))
	case MsgVoteReply:
		return fmt.Sprintf("votereply %d %d %d", m.Term, b2i(m.Granted), b2i(m.Pre))
	case MsgAppend:
		return fmt.Sprintf("append %d %d %d %d %s", m.Term, m.PrevIndex, m.PrevTerm, m.Commit, fmtEntries(m.Entries))
	default:
		return fmt.Sprintf("appendreply %d %d %d", m.Term, b2i(m.Success), m.Index)
	}
}

func u(s string) uint64 { v, _ := strconv.ParseUint(s, 10, 64); return v }

func parseMsg(w []string) Msg {
	switch w[0] {
	case "vote":
		return Msg{Kind: MsgVote, Term: Term(u(w[1])), LastIndex: Index(u(w[2])), LastTerm: Term(u(w[3])), Pre: u(w[4]) == 1}
	case "votereply":
		return Msg{Kind: MsgVoteReply, Term: Term(u(w[1])), Granted: u(w[2]) == 1, Pre: u(w[3]) == 1}
	case "append":
		return Msg{Kind: MsgAppend, Term: Term(u(w[1])), PrevIndex: Index(u(w[2])), PrevTerm: Term(u(w[3])), Commit: Index(u(w[4])), Entries: parseEntries(w[5])}
	case "appendreply":
		return Msg{Kind: MsgAppendReply, Term: Term(u(w[1])), Success: u(w[2]) == 1, Index: Index(u(w[3]))}
	}
	panic("unknown message " + w[0])
}

func fmtEffect(e Effect) string {
	switch e.Kind {
	case EffSend:
		return fmt.Sprintf("send %d %s", e.To, fmtMsg(e.Msg))
	case EffPersist:
		p := e.Persist
		vote, comp := "-", "-"
		if p.VotedFor != None {
			vote = strconv.Itoa(p.VotedFor)
		}
		if p.HasCompact {
			comp = fmt.Sprintf("%d:%d", p.CompactIdx, p.CompactTrm)
		}
		return fmt.Sprintf("persist %d %d %s %d %s %s", p.Token, p.Term, vote, p.From, comp, fmtEntries(p.Entries))
	case EffApply:
		return fmt.Sprintf("apply %d %s", e.Index, fmtEntry(e.Entry))
	case EffNeedSnapshot:
		return fmt.Sprintf("needsnap %d %d %d", e.To, e.Index, e.Term)
	default:
		return fmt.Sprintf("restore %d %d", e.Index, e.Term)
	}
}

func fmtState(n *Node) string {
	l := "-"
	if n.Leader() != None {
		l = strconv.Itoa(n.Leader())
	}
	return fmt.Sprintf("state role=%s term=%d leader=%s commit=%d applied=%d base=%d last=%d",
		n.Role(), n.Term(), l, n.CommitIndex(), n.AppliedIndex(), n.Base(), n.LastIndex())
}

func field(line, key string) string {
	for _, w := range strings.Fields(line) {
		if strings.HasPrefix(w, key+"=") {
			return w[len(key)+1:]
		}
	}
	panic("missing " + key)
}

func parseNode(line string) *Node {
	var peers []NodeID
	for _, p := range strings.Split(field(line, "peers"), ",") {
		peers = append(peers, NodeID(u(p)))
	}
	cfg := Config{
		ElectionTicks: uint32(u(field(line, "election"))), HeartbeatTicks: uint32(u(field(line, "heartbeat"))),
		MaxBatch: int(u(field(line, "batch"))), PreVote: field(line, "prevote") == "1",
	}
	d := strings.SplitN(field(line, "disk"), ":", 5)
	disk := Disk{Term: Term(u(d[0])), VotedFor: None, Base: Index(u(d[2])), BaseTerm: Term(u(d[3])), Log: parseEntries(d[4])}
	if d[1] != "-" {
		disk.VotedFor = int(u(d[1]))
	}
	return NewNode(NodeID(u(field(line, "id"))), peers, cfg, u(field(line, "seed")), disk)
}

func replay(t *testing.T, name string, f *os.File) int {
	var node *Node
	var expected []string
	checked := 0
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	ln := 0
	for sc.Scan() {
		ln++
		line := sc.Text()
		w := strings.Fields(line)
		if len(w) == 0 {
			continue
		}
		switch w[0] {
		case "node":
			node = parseNode(line)
		case "in":
			switch w[1] {
			case "tick":
				node.Tick()
			case "step":
				node.Step(NodeID(u(w[2])), parseMsg(w[3:]))
			case "propose":
				node.Propose(unhex(w[2]))
			case "replicate":
				node.Replicate()
			case "persisted":
				node.Persisted(u(w[2]))
			case "compact":
				node.Compact(Index(u(w[2])))
			case "install":
				node.InstallSnapshot(NodeID(u(w[2])), Term(u(w[3])), Index(u(w[4])), Term(u(w[5])))
			default:
				t.Fatalf("%s:%d: unknown input %s", name, ln, w[1])
			}
		case "out", "state":
			expected = append(expected, line)
			if w[0] == "state" {
				var got []string
				for _, e := range node.TakeEffects() {
					got = append(got, "out "+fmtEffect(e))
				}
				got = append(got, fmtState(node))
				if strings.Join(got, "\n") != strings.Join(expected, "\n") {
					i := 0
					for i < len(got) && i < len(expected) && got[i] == expected[i] {
						i++
					}
					want, have := "<end>", "<end>"
					if i < len(expected) {
						want = expected[i]
					}
					if i < len(got) {
						have = got[i]
					}
					t.Fatalf("%s:%d: output differs at item %d\n  want: %s\n  got:  %s", name, ln, i, want, have)
				}
				checked++
				expected = expected[:0]
			}
		case "#":
		default:
			t.Fatalf("%s:%d: unknown line kind %s", name, ln, w[0])
		}
	}
	return checked
}

func TestReplicationConformanceVectors(t *testing.T) {
	files, _ := filepath.Glob("../vectors/replication/*.trace")
	sort.Strings(files)
	if len(files) == 0 {
		t.Fatal("no traces in ../vectors/replication")
	}
	total := 0
	for _, path := range files {
		f, err := os.Open(path)
		if err != nil {
			t.Fatal(err)
		}
		n := replay(t, filepath.Base(path), f)
		f.Close()
		if n <= 100 {
			t.Errorf("%s: only %d checked steps", path, n)
		}
		total += n
	}
	t.Logf("replayed %d traces, %d drain points", len(files), total)
}
